import React, { useState } from "react";
import { AppointmentForm } from "../../components/appointmentForm/AppointmentForm";
import { TileList } from "../../components/tileList/TileList";

export const AppointmentsPage = () => {
  // Define state variables for appointment info
  const [title, setTitle] = useState("");
  const [contact, setContact] = useState("");
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");
  // Define state for the list of appointments
  const [appointments, setAppointments] = useState([]);

  // Handle form submission: add the appointment and clear the form if all fields are provided
  const handleSubmit = (e) => {
    e.preventDefault();
    // (Optional) You can add more validation here if needed
    setAppointments((prevAppointments) => [
      ...prevAppointments,
      { title, contact, date, time },
    ]);
    // Clear the form fields after successful submission
    setTitle("");
    setContact("");
    setDate("");
    setTime("");
  };

  return (
    <div>
      <section>
        <h2>Add Appointment</h2>
        <AppointmentForm
          title={title}
          setTitle={setTitle}
          contact={contact}
          setContact={setContact}
          date={date}
          setDate={setDate}
          time={time}
          setTime={setTime}
          handleSubmit={handleSubmit}
          // If there are no contacts provided by props, pass an empty array (or modify as needed)
          contacts={[]}
        />
      </section>
      <hr />
      <section>
        <h2>Appointments</h2>
        <TileList data={appointments} />
      </section>
    </div>
  );
};
